import type { OrchestrationV2ModelExecution } from "@t3tools/contracts";
import { describe, expect, it } from "vite-plus/test";
import { modelExecutionDetail, modelExecutionSummary } from "./modelExecution.ts";

const phase: OrchestrationV2ModelExecution = {
  version: 1,
  kind: "phase",
  nativeSessionId: "session-1",
  eventId: "event-1",
  sourceTimestamp: "2026-11-02T10:00:05.000Z",
  receivedAt: "2026-11-02T10:00:08.000Z",
  status: "completed",
  model: "actual-model",
  startSource: "observed",
  startedAt: "2026-11-02T10:00:00.000Z",
  endedAt: "2026-11-02T10:00:05.000Z",
  durationMs: 4800,
  gaps: [],
};

describe("model execution presentation", () => {
  it("uses provider duration rather than receipt latency and distinguishes timing evidence", () => {
    expect(modelExecutionSummary(phase)).toContain("actual-model · completed · 4.8s");
    const detail = modelExecutionDetail(phase);
    expect(detail).toContain("Provider elapsed: 4.8s");
    expect(detail).toContain(`Started (observed): ${phase.startedAt}`);
    expect(detail).toContain(`Provider event time: ${phase.sourceTimestamp}`);
    expect(detail).toContain(`Received: ${phase.receivedAt}`);
    expect(modelExecutionDetail({ ...phase, startSource: "estimated" })).toContain(
      `Started (estimated): ${phase.startedAt}`,
    );
    const { durationMs: _duration, ...withoutDuration } = phase;
    expect(modelExecutionSummary(withoutDuration)).not.toContain("5.0s");
    expect(modelExecutionDetail(withoutDuration)).toContain("Provider elapsed: not reported");
    expect(
      modelExecutionDetail({ ...phase, startSource: "unknown", startedAt: undefined }),
    ).toContain("Start: unknown");
  });

  it("keeps requested routing separate from effective, pending, and actual execution", () => {
    const route = {
      ...phase,
      kind: "route" as const,
      requestedModel: "Fusion",
      requestedPreference: "premium",
      effectivePreference: "standard",
      pendingPreference: "premium",
      activatingPreference: null,
    };
    expect(modelExecutionSummary(route)).not.toContain("actual-model");
    const detail = modelExecutionDetail(route);
    expect(detail).toContain("Routing state (not proof of model execution)");
    expect(detail).toContain("Requested model: Fusion");
    expect(detail).toContain("Requested routing: premium");
    expect(detail).toContain("Effective routing: standard");
    expect(detail).toContain("Pending routing: premium");
    expect(detail).toContain("Activating routing: none");
    expect(modelExecutionDetail({ ...route, pendingPreference: undefined })).not.toContain(
      "Pending routing:",
    );
  });

  it("surfaces fallback, failure, final provenance and incomplete telemetry without inventing success", () => {
    const failed = {
      ...phase,
      status: "failed",
      fallbackModel: "fallback-model",
      finalSourceModel: "final-model",
      finalSourcePhaseId: "final-phase",
      reason: "Provider unavailable",
      awaitingBackgroundWork: true,
      gaps: ["missing phase start", "duration incomplete"],
    };
    expect(modelExecutionSummary(failed)).toContain("failed");
    expect(modelExecutionSummary(failed)).toContain("final final-model");
    expect(modelExecutionSummary(failed)).toContain("telemetry gaps");
    const detail = modelExecutionDetail(failed);
    expect(detail).toContain("Planned fallback model (not execution evidence): fallback-model");
    expect(detail).toContain("Final source model: final-model");
    expect(detail).toContain("Final source phase: final-phase");
    expect(detail).toContain("Reason: Provider unavailable");
    expect(detail).toContain("Background work: awaiting completion");
    expect(detail).toContain("Telemetry gaps:\n- missing phase start\n- duration incomplete");
  });

  it("shows Fusion patterns and final models without reporting planned fallback as executed", () => {
    for (const pattern of ["single", "cascade", "critique"]) {
      const route: OrchestrationV2ModelExecution = {
        ...phase,
        kind: "route",
        pattern,
        syntheticModel: "opaque-fusion",
        finalSourceModel: "actual-final-model",
        fallbackModel: "unused-fallback",
      };
      expect(modelExecutionSummary(route)).toContain(`opaque-fusion · ${pattern}`);
      expect(modelExecutionSummary(route)).toContain("final actual-final-model");
      expect(modelExecutionSummary(route)).toContain("planned fallback unused-fallback");
    }
  });

  it("shows ordinary Auto resolution as selection rather than Fusion or final execution", () => {
    const resolved: OrchestrationV2ModelExecution = {
      ...phase,
      kind: "route",
      requestedModel: "auto",
      status: "resolved",
    };
    expect(modelExecutionSummary(resolved)).toContain("selected actual-model");
    expect(modelExecutionSummary(resolved)).not.toContain("final ");
    expect(modelExecutionDetail(resolved)).toContain(
      "Selected model (not execution evidence): actual-model",
    );
    expect(modelExecutionDetail(resolved)).not.toContain("Pattern:");
  });
});

import type { OrchestrationV2ModelExecution } from "@t3tools/contracts";
import { formatDuration } from "@t3tools/shared/orchestrationTiming";

export function modelExecutionSummary(execution: OrchestrationV2ModelExecution): string {
  const subject =
    execution.kind === "phase"
      ? ["Model phase", execution.model ?? "model unknown", execution.role]
      : execution.kind === "gap"
        ? ["Model telemetry gap", execution.model]
        : [
            execution.kind === "selection" ? "Model selection (requested)" : "Model routing",
            execution.syntheticModel ?? execution.requestedModel,
            execution.pattern,
            execution.status === "resolved" && execution.model
              ? `selected ${execution.model}`
              : undefined,
            execution.effectivePreference
              ? `effective ${execution.effectivePreference}`
              : execution.requestedPreference
                ? `requested ${execution.requestedPreference}`
                : undefined,
          ];
  return [
    ...subject,
    execution.status,
    execution.kind === "phase" && execution.durationMs !== undefined
      ? formatDuration(execution.durationMs)
      : undefined,
    execution.finalSourceModel ? `final ${execution.finalSourceModel}` : undefined,
    execution.fallbackModel ? `planned fallback ${execution.fallbackModel}` : undefined,
    execution.gaps.length > 0 ? "telemetry gaps" : undefined,
  ]
    .filter(Boolean)
    .join(" · ");
}

export function modelExecutionDetail(
  execution: OrchestrationV2ModelExecution,
  message?: string,
): string {
  const lines: string[] = message?.trim() ? [message.trim(), ""] : [];
  const add = (label: string, value: string | number | null | undefined) => {
    if (value !== undefined) lines.push(`${label}: ${value === null ? "none" : value}`);
  };
  lines.push(
    execution.kind === "selection" || execution.kind === "route"
      ? "Routing state (not proof of model execution)"
      : execution.kind === "gap"
        ? "Incomplete model execution telemetry"
        : "Provider-reported model phase",
  );
  add("Status", execution.status);
  add(
    execution.kind === "route" ? "Selected model (not execution evidence)" : "Model",
    execution.model,
  );
  add("Role", execution.role);
  add("Phase kind", execution.phaseKind);
  add("Conversation scope", execution.conversationScope);
  add("Pattern", execution.pattern);
  if (execution.plannedModels?.length)
    lines.push(
      `Planned models (not execution evidence):\n${execution.plannedModels
        .map(
          (phase) => `- ${phase.role}: ${phase.model}${phase.phaseId ? ` (${phase.phaseId})` : ""}`,
        )
        .join("\n")}`,
    );
  add("Requested model", execution.requestedModel);
  add("Resolved virtual model", execution.syntheticModel);
  add("Requested routing", execution.requestedPreference);
  add("Effective routing", execution.effectivePreference);
  add("Pending routing", execution.pendingPreference);
  add("Activating routing", execution.activatingPreference);
  add(
    execution.startedAt ? `Started (${execution.startSource})` : "Start",
    execution.startedAt ?? execution.startSource,
  );
  add("Ended", execution.endedAt);
  add(
    "Provider elapsed",
    execution.durationMs === undefined ? "not reported" : formatDuration(execution.durationMs),
  );
  add(
    execution.kind === "selection"
      ? "Snapshot time"
      : execution.kind === "gap"
        ? "Gap detected"
        : "Provider event time",
    execution.sourceTimestamp,
  );
  add("Received", execution.receivedAt);
  add("Planned fallback model (not execution evidence)", execution.fallbackModel);
  add("Degraded to phase", execution.degradedToPhaseId);
  add("Final source model", execution.finalSourceModel);
  add("Final source phase", execution.finalSourcePhaseId);
  add("Reason", execution.reason);
  if (execution.awaitingBackgroundWork !== undefined) {
    add(
      "Background work",
      execution.awaitingBackgroundWork ? "awaiting completion" : "not pending",
    );
  }
  if (execution.endedWithBackgroundWork !== undefined)
    add("Phase ended with background work", execution.endedWithBackgroundWork ? "yes" : "no");
  add("Session", execution.nativeSessionId);
  add("Turn", execution.nativeTurnId);
  add("Fusion", execution.fusionId);
  add("Phase", execution.phaseId);
  add("Event", execution.eventId);
  add("Contract version", execution.contractVersion);
  if (execution.gaps.length > 0)
    lines.push(`Telemetry gaps:\n${execution.gaps.map((gap) => `- ${gap}`).join("\n")}`);
  return lines.join("\n");
}

import { assert, describe, it } from "@effect/vitest";
import type {
  CopilotSession,
  MessageOptions,
  SessionConfig,
  SessionEvent,
} from "@github/copilot-sdk";
import {
  DEFAULT_SERVER_SETTINGS,
  MessageId,
  NodeId,
  ProjectId,
  ProviderInstanceId,
  ProviderSessionId,
  RunAttemptId,
  RunId,
  ThreadId,
  type OrchestrationV2AppThread,
  type ModelSelection,
} from "@t3tools/contracts";
import * as DateTime from "effect/DateTime";
import * as Effect from "effect/Effect";
import * as Exit from "effect/Exit";
import * as Fiber from "effect/Fiber";
import * as Queue from "effect/Queue";
import * as Schema from "effect/Schema";
import * as Stream from "effect/Stream";
import * as ProviderAdapter from "@t3tools/provider-core/server/ProviderAdapter";
import * as ProviderHost from "@t3tools/provider-core/server/ProviderHost";
import * as McpProviderSessions from "@t3tools/provider-core/server/McpProviderSessions";
import { CopilotSettings } from "../settings.ts";
import { makeAdapter, type ClientHandle, type SessionHandle } from "./adapter.ts";
import type { ModelCatalog } from "./routing.ts";

const threadId = ThreadId.make("copilot-test");
const instanceId = ProviderInstanceId.make("githubCopilot");
const sessionId = ProviderSessionId.make("copilot-runtime");
const selection = { instanceId, model: "gpt-4.1", options: [] };
const policy: ProviderAdapter.ProviderAdapterV2RuntimePolicy = {
  cwd: "/workspace",
  runtimeMode: "approval-required",
  interactionMode: "default",
};
const settings = Schema.decodeSync(CopilotSettings)({});
const host = ProviderHost.ProviderHost.of({
  paths: {
    cwd: "/workspace",
    baseDir: "/test",
    stateDir: "/test/state",
    providerStatusCacheDir: "/test/cache",
    attachmentsDir: "/test/attachments",
  },
  settings: {
    get: Effect.succeed(DEFAULT_SERVER_SETTINGS),
    withSnapshot: (use) => use(DEFAULT_SERVER_SETTINGS),
    changes: Stream.empty,
    subscribe: Effect.succeed(Stream.empty),
  },
  shouldRunBackgroundWork: () => Effect.succeed(false),
  resolveAttachmentPath: (attachment) => `/test/attachments/${attachment.id}`,
  credentials: () =>
    Effect.succeed({
      binding: { owner: "t3", key: "test" },
      get: Effect.succeedNone,
      set: () => Effect.void,
      remove: Effect.void,
    }),
});

function fakeSdk() {
  let config: SessionConfig | undefined;
  let serial = 0;
  let disconnected = 0;
  let stopped = 0;
  let resumed: string | undefined;
  let conflict = false;
  let continuePendingWork: boolean | undefined;
  const permissionReplies: Array<
    Parameters<CopilotSession["rpc"]["permissions"]["handlePendingPermissionRequest"]>[0]
  > = [];
  let permissionResponse = async (): Promise<{ success: boolean }> => ({ success: true });
  let background: Awaited<ReturnType<SessionHandle["rpc"]["tasks"]["list"]>> = { tasks: [] };
  let catalog: ModelCatalog = { models: [] };
  let current: Awaited<ReturnType<SessionHandle["rpc"]["model"]["getCurrent"]>> = {
    modelId: "gpt-4.1",
  };
  const modelChanges: Array<{ model: string; options: Parameters<SessionHandle["setModel"]>[1] }> =
    [];
  const sent: MessageOptions[] = [];
  const emit = (
    type: SessionEvent["type"],
    data: unknown = {},
    agentId?: string,
    timestamp = "2026-10-29T00:00:00Z",
  ) => {
    config?.onEvent?.({
      type,
      data,
      id: `native-event-${++serial}`,
      timestamp,
      parentId: null,
      ...(agentId ? { agentId } : {}),
    } as SessionEvent);
  };
  const session: SessionHandle = {
    sessionId: "native-copilot",
    send: async (message) => {
      sent.push(typeof message === "string" ? { prompt: message } : message);
      return "native-user-message";
    },
    abort: async () => {
      emit("session.idle");
    },
    disconnect: async () => {
      disconnected++;
    },
    getEvents: async () => [],
    setModel: async (model, options) => {
      modelChanges.push({ model, options });
    },
    rpc: {
      model: {
        list: async () => ({ list: [], ...(catalog.auto ? { auto: catalog.auto } : {}) }),
        getCurrent: async () => current,
      },
      mode: { set: async () => ({ status: "success", modelChanged: false, modeApplied: true }) },
      plan: {
        read: async () => ({
          exists: true,
          content: "# Plan\n\nImplement safely",
          path: "/copilot/plan.md",
        }),
      },
      skills: { list: async () => ({ skills: [] }) },
      tasks: { list: async () => background, cancel: async () => ({ cancelled: true }) },
      permissions: {
        handlePendingPermissionRequest: async (
          response: Parameters<
            CopilotSession["rpc"]["permissions"]["handlePendingPermissionRequest"]
          >[0],
        ) => {
          permissionReplies.push(response);
          return permissionResponse();
        },
      },
    },
  };
  const client: ClientHandle = {
    rpc: { models: { list: async () => catalog } },
    start: async () => {},
    stop: async () => {
      stopped++;
      return [];
    },
    forceStop: async () => {},
    createSession: async (created) => {
      config = created;
      emit("session.idle");
      return session;
    },
    resumeSession: async (id, created) => {
      resumed = id;
      continuePendingWork = created.continuePendingWork;
      config = created;
      emit("session.resume", { alreadyInUse: conflict });
      return session;
    },
  };
  return {
    client,
    session,
    sent,
    emit,
    modelChanges,
    setCatalog: (value: ModelCatalog) => {
      catalog = value;
    },
    setCurrent: (value: typeof current) => {
      current = value;
    },
    get config() {
      return config!;
    },
    get resumed() {
      return resumed;
    },
    get continuePendingWork() {
      return continuePendingWork;
    },
    get disconnected() {
      return disconnected;
    },
    get stopped() {
      return stopped;
    },
    conflict: () => {
      conflict = true;
    },
    setTasks: (tasks: typeof background) => {
      background = tasks;
    },
    permissionReplies,
    setPermissionResponse: (response: () => Promise<{ success: boolean }>) => {
      permissionResponse = response;
    },
  };
}
type Fake = ReturnType<typeof fakeSdk>;
const durablePhase = (phaseId: string): SessionEvent => ({
  type: "assistant.fusion_phase_completed",
  id: `durable-${phaseId}`,
  timestamp: "2026-10-29T00:00:02Z",
  parentId: null,
  data: {
    fusionId: "fusion-1",
    phaseId,
    model: "model",
    role: "primary",
    phaseKind: "primary",
    conversationScope: "root",
    durationMs: 2000,
    status: "succeeded",
    content: "PRIVATE",
    verdict: null,
    usage: { inputTokens: 10, outputTokens: 5, cachedTokens: 0, requestCount: 1, totalNanoAiu: 0 },
  },
});

function promiseGate() {
  let resolve!: () => void;
  const promise = new Promise<void>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}

const setup = Effect.fnUntraced(function* (
  fake: Fake,
  initialNativeThreadId?: string,
  initialSelection: ModelSelection = selection,
  runtimeSessionId = sessionId,
) {
  const adapter = yield* makeAdapter(
    { instanceId, settings, environment: { HOME: "/test-account" } },
    { clientFactory: () => fake.client },
  );
  const runtime = yield* adapter.openSession({
    threadId,
    providerSessionId: runtimeSessionId,
    modelSelection: initialSelection,
    runtimePolicy: policy,
    ...(initialNativeThreadId ? { initialNativeThreadId } : {}),
  });
  const emitted: ProviderAdapter.ProviderAdapterV2Event[] = [];
  const eventQueue = yield* Queue.unbounded<ProviderAdapter.ProviderAdapterV2Event>();
  yield* runtime.events.pipe(
    Stream.runForEach((event) =>
      Effect.sync(() => {
        emitted.push(event);
      }).pipe(Effect.andThen(Queue.offer(eventQueue, event))),
    ),
    Effect.forkScoped,
  );
  const takeEvent = Effect.fnUntraced(function* (
    predicate: (event: ProviderAdapter.ProviderAdapterV2Event) => boolean,
  ) {
    while (true) {
      const event = yield* Queue.take(eventQueue);
      if (predicate(event)) return event;
    }
  });
  const thread = yield* runtime.ensureThread({
    threadId,
    modelSelection: initialSelection,
    runtimePolicy: policy,
  });
  const start = Effect.fnUntraced(function* (ordinal = 1, turnSelection = initialSelection) {
    const now = yield* DateTime.now;
    const appThread: OrchestrationV2AppThread = {
      id: threadId,
      projectId: ProjectId.make("project"),
      title: "Test",
      providerInstanceId: instanceId,
      modelSelection: turnSelection,
      runtimeMode: policy.runtimeMode,
      interactionMode: "default",
      branch: null,
      worktreePath: null,
      activeProviderThreadId: thread.id,
      lineage: { parentThreadId: null, relationshipToParent: null, rootThreadId: threadId },
      forkedFrom: null,
      createdBy: "user",
      creationSource: "web",
      createdAt: now,
      updatedAt: now,
      archivedAt: null,
      settledOverride: null,
      settledAt: null,
      lastVisitedAt: null,
      deletedAt: null,
    };
    yield* runtime.startTurn({
      appThread,
      threadId,
      runId: RunId.make(`run-${ordinal}`),
      runOrdinal: ordinal,
      providerTurnOrdinal: ordinal,
      attemptId: RunAttemptId.make(`attempt-${ordinal}`),
      rootNodeId: NodeId.make(`root-${ordinal}`),
      providerThread: thread,
      message: {
        messageId: MessageId.make(`user-${ordinal}`),
        text: "Hello",
        attachments: [],
        createdBy: "user",
        creationSource: "web",
      },
      modelSelection: turnSelection,
      runtimePolicy: policy,
    });
  });
  const drain = () => runtime.readThreadSnapshot({ providerThread: thread });
  return { runtime, thread, emitted, start, drain, takeEvent };
});

const provide = <A, E, R>(effect: Effect.Effect<A, E, R>) =>
  effect.pipe(
    Effect.provideService(ProviderHost.ProviderHost, host),
    Effect.provide(McpProviderSessions.layer),
    Effect.scoped,
  );

describe("native Copilot V2", () => {
  it.effect(
    "reimports duplicate Auto resolution with a stable item identity across cold starts",
    () =>
      provide(
        Effect.gen(function* () {
          const ids: string[] = [];
          for (let restart = 0; restart < 2; restart++) {
            const fake = fakeSdk();
            fake.session.getEvents = async () => [
              {
                type: "session.auto_mode_resolved",
                id: "durable-auto",
                parentId: "chronological-not-semantic",
                timestamp: "2026-10-29T00:00:02Z",
                data: {
                  chosenModel: "actual-model",
                  fallback: false,
                  candidateModels: ["actual-model"],
                  categoryScores: { needs_reasoning: 0 },
                  routingMethod: "auto_v2",
                },
              },
            ];
            const { takeEvent } = yield* setup(
              fake,
              "native-copilot",
              selection,
              ProviderSessionId.make(`auto-restart-${restart}`),
            );
            const imported = yield* takeEvent(
              (event) =>
                event.type === "turn_item.updated" &&
                event.turnItem.type === "system_notice" &&
                event.turnItem.modelExecution?.eventId === "durable-auto",
            );
            if (imported.type !== "turn_item.updated" || imported.turnItem.type !== "system_notice")
              return assert.fail("Expected Auto history");
            ids.push(imported.turnItem.id);
            assert.equal(imported.turnItem.modelExecution?.model, "actual-model");
            assert.equal(imported.turnItem.runId, null);
            assert.isUndefined(imported.turnItem.modelExecution?.finalSourceModel);
          }
          assert.equal(ids[0], ids[1]);
        }),
      ),
  );

  it.effect(
    "persists Auto resolutions without assigning chronological-only events to a user turn",
    () =>
      provide(
        Effect.gen(function* () {
          const fake = fakeSdk();
          const { start, takeEvent, drain } = yield* setup(fake);
          yield* start();
          fake.emit("session.auto_mode_resolved", {
            chosenModel: "actual-model",
            routingMethod: "auto_v2",
          });
          const reported = yield* takeEvent(
            (event) =>
              event.type === "turn_item.updated" &&
              event.turnItem.type === "system_notice" &&
              event.turnItem.modelExecution?.status === "resolved",
          );
          if (reported.type !== "turn_item.updated" || reported.turnItem.type !== "system_notice")
            return assert.fail("Expected routing metadata");
          assert.equal(reported.turnItem.modelExecution?.model, "actual-model");
          assert.equal(reported.turnItem.runId, null);
          assert.isUndefined(reported.turnItem.modelExecution?.pattern);
          assert.equal((yield* drain()).providerTurns[0]?.status, "running");
        }),
      ),
  );

  it.effect(
    "reattaches phase and completion received before route and turn-start for every pattern",
    () =>
      provide(
        Effect.gen(function* () {
          for (const pattern of ["single", "cascade", "critique"]) {
            const fake = fakeSdk();
            const { start, drain, emitted, takeEvent } = yield* setup(fake);
            yield* start();
            fake.emit("assistant.fusion_phase_completed", {
              fusionId: "fusion-ordered",
              phaseId: "primary",
              model: "actual-model",
              role: "primary",
              phaseKind: "primary",
              conversationScope: "root",
              status: "succeeded",
              durationMs: 2000,
              content: "PRIVATE DRAFT",
            });
            fake.emit("session.fusion_completed", {
              fusionId: "fusion-ordered",
              turnId: "0",
              pattern,
              syntheticModel: "opaque-fusion",
              outcome: "completed",
              durationMs: 2000,
              finalSourceModel: "actual-model",
              finalSourcePhaseId: "primary",
            });
            fake.emit("assistant.turn_start", { turnId: "0" });
            fake.emit("session.fusion_resolved", {
              fusionId: "fusion-ordered",
              turnId: "0",
              pattern,
              contractVersion: 1,
              syntheticModel: "opaque-fusion",
              primaryModel: "planned-model",
              fallbackModel: "unused-fallback",
            });
            yield* takeEvent(
              (event) =>
                event.type === "turn_item.updated" &&
                event.turnItem.type === "system_notice" &&
                event.turnItem.modelExecution?.fusionId === "fusion-ordered" &&
                event.turnItem.modelExecution?.kind === "route" &&
                event.turnItem.modelExecution?.plannedModels !== undefined,
            );
            const beforeIdle = yield* drain();
            assert.equal(beforeIdle.providerTurns.length, 1);
            assert.equal(beforeIdle.providerTurns[0]?.status, "running");
            const items = new Map(
              emitted.flatMap((event) =>
                event.type === "turn_item.updated"
                  ? [[event.turnItem.id, event.turnItem] as const]
                  : [],
              ),
            );
            const metadata = [...items.values()].filter(
              (item) =>
                item.type === "system_notice" && item.modelExecution?.fusionId === "fusion-ordered",
            );
            assert.equal(metadata.length, 2);
            assert.isTrue(metadata.every((item) => item.runId === RunId.make("run-1")));
            const route = metadata.find(
              (item) => item.type === "system_notice" && item.modelExecution?.kind === "route",
            );
            if (route?.type !== "system_notice") return assert.fail("Expected route metadata");
            assert.equal(route.modelExecution?.pattern, pattern);
            assert.equal(route.modelExecution?.status, "completed");
            assert.equal(route.modelExecution?.finalSourceModel, "actual-model");
            assert.deepEqual(route.modelExecution?.gaps, []);
            assert.notInclude(JSON.stringify(metadata), "PRIVATE DRAFT");
            fake.emit("assistant.message", {
              messageId: "final-response",
              content: "Demo final result",
            });
            fake.emit("session.idle");
            const completed = yield* drain();
            assert.equal(completed.providerTurns.length, 1);
            assert.equal(completed.providerTurns[0]?.status, "completed");
          }
        }),
      ),
  );

  it.effect(
    "bounds live phase records and exposes an overflow gap instead of silently losing telemetry",
